    int id;
    int score;
} Student;
```
Implement in `exercise.c`:
1. `Student create_student(int id, int score)`: Returns initialized struct.
2. `void boost_score(Student *s, int points)`: Adds points to score capped at 100.
3. `int find_top_student(const Student *students, int count)`: Returns `id` of top score (-1 if count <= 0).

## Reference Solution

<details>
<summary>Click to reveal reference solution</summary>

```c
typedef struct {
    int id;
    int score;
} Student;

Student create_student(int id, int score) {
    Student s;
    s.id = id;
    s.score = score;
    return s;
}

void boost_score(Student *s, int points) {
    if (s == 0) return;
    s->score += points;
    if (s->score > 100) s->score = 100;
}

int find_top_student(const Student *students, int count) {
    if (students == 0 || count <= 0) return -1;
    int best_id = students[0].id;
    int best_score = students[0].score;
    for (int i = 1; i < count; i++) {
        if (students[i].score > best_score) {
            best_score = students[i].score;
            best_id = students[i].id;
        }
    }
    return best_id;
}
```
