4. `void free_list(Node *head)`: Deallocates entire list.

## Reference Solution

<details>
<summary>Click to reveal reference solution</summary>

```c
#include <stdlib.h>

typedef struct Node { int data; struct Node *next; } Node;

Node* create_node(int data) {
    Node *n = (Node *)malloc(sizeof(Node));
    if (n == 0) return 0;
    n->data = data;
    n->next = 0;
    return n;
}

void append_node(Node **head, int data) {
    if (head == 0) return;
    Node *new_node = create_node(data);
    if (*head == 0) {
        *head = new_node;
        return;
    }
    Node *curr = *head;
    while (curr->next != 0) curr = curr->next;
    curr->next = new_node;
}

int count_list(const Node *head) {
    int count = 0;
    const Node *curr = head;
    while (curr != 0) {
        count++;
        curr = curr->next;
    }
    return count;
}

void free_list(Node *head) {
    Node *curr = head;
    while (curr != 0) {
        Node *next = curr->next;
        free(curr);
        curr = next;
    }
}
```
