#define STACK_MAX 16
typedef struct { int items[STACK_MAX]; int top; } FixedStack;

void stack_init(FixedStack *s) {
    if (s == 0) return;
    s->top = 0;
}

int stack_push(FixedStack *s, int val) {
    if (s == 0 || s->top >= STACK_MAX) return -1;
    s->items[s->top] = val;
    s->top++;
    return 0;
}

